package com.bank.ref;

import java.util.logging.Logger;

public class ReferenceDecoder {

    private static final Logger log = Logger.getLogger(ReferenceDecoder.class.getName());

    public int numDecodings(String s) {
        int n = s.length();
        if (n == 0 || s.charAt(0) == '0') return 0;
        int[] dp = new int[n + 1];
        dp[0] = 1;                                     // empty string: one way
        dp[1] = 1;                                     // first digit is non-zero here
        for (int i = 2; i <= n; i++) {
            if (s.charAt(i - 1) != '0') {              // single digit 1..9 valid
                dp[i] += dp[i - 1];
            }
            int two = Integer.parseInt(s.substring(i - 2, i));
            if (two >= 10 && two <= 26) {              // two-digit 10..26 valid
                dp[i] += dp[i - 2];
            }
        }
        int result = dp[n];
        log.info(() -> "numDecodings(" + s + ") = " + result);
        return result;
    }
}
