package com.bank.ref;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DecodeWaysDemo {

    private static final Logger log = Logger.getLogger(DecodeWaysDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reference Decoder (Decode Ways)");
        ReferenceDecoder decoder = new ReferenceDecoder();
        log.info("'226' → " + decoder.numDecodings("226")); // 3 (BZ, VF, BBF)
        log.info("'06' → " + decoder.numDecodings("06"));    // 0 (leading zero)
    }
}
